function markExisting(){const root=$('#article');if(!root)return;for(const n of topic.notes){if(!n.anchor||n.anchor.file!==file||!n.anchor.quote)continue;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];let node,text='';while(node=walker.nextNode()){nodes.push({node,start:text.length});text+=node.data}const match=/^text:offset:(\d+)$/.exec(n.anchor.locator);let start=match?Number(match[1]):-1;if(start<0||text.slice(start,start+n.anchor.quote.length)!==n.anchor.quote){let best=null;for(let pos=text.indexOf(n.anchor.quote);pos!==-1;pos=text.indexOf(n.anchor.quote,pos+1)){let score=0;const prefix=n.anchor.prefix||'',suffix=n.anchor.suffix||'';for(let i=1;i<=prefix.length&&i<=pos&&prefix[prefix.length-i]===text[pos-i];i++)score++;for(let i=0;i<suffix.length&&suffix[i]===text[pos+n.anchor.quote.length+i];i++)score++;const distance=start>=0?Math.abs(pos-start):pos;if(!best||score>best.score||score===best.score&&distance<best.distance)best={pos,score,distance}}start=best?best.pos:-1;}if(start<0)continue;const end=start+n.anchor.quote.length;for(const part of nodes){const a=Math.max(0,start-part.start),b=Math.min(part.node.length,end-part.start);if(a>=b)continue;const range=document.createRange();range.setStart(part.node,a);range.setEnd(part.node,b);const mark=document.createElement('mark');range.surroundContents(mark)}}renderTraining();if(tab==='chat'&&state.plugins.some(p=>p.id==='guide-acp'&&p.state==='active'))updateQuickActions().catch(notify)}
