function clearSpeechMark(){document.querySelectorAll('[data-speech-active="true"]').forEach(mark=>{const parent=mark.parentNode;mark.replaceWith(...mark.childNodes);if(parent)parent.normalize()})}
let speechAbort=null,speechAudio=null,speechUrl=null,speechLoopA=null,speechLoopB=null;
function updateSpeechDeck(){if(!speechAudio)return;if(speechLoopA!==null&&speechLoopB!==null&&speechAudio.currentTime>=speechLoopB)speechAudio.currentTime=speechLoopA;const fmt=value=>{const n=Number.isFinite(value)?Math.floor(value):0;return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')};const time=$('[data-speech-time]'),seek=$('[data-speech-seek]');if(time)time.textContent=fmt(speechAudio.currentTime)+' / '+fmt(speechAudio.duration);if(seek){seek.max=Number.isFinite(speechAudio.duration)?speechAudio.duration:0;seek.value=speechAudio.currentTime}}
