function speechChapterRoot(article,reader,selected,paged){const chapters=[...article.querySelectorAll('.pith-epub-chapter')];if(!chapters.length)return article;if(selected){const chapter=selected.closest('.pith-epub-chapter');return chapter&&article.contains(chapter)?chapter:null}const viewport=reader.getBoundingClientRect();let best=null;for(const chapter of chapters)for(const rect of chapter.getClientRects()){if(rect.right<=viewport.left||rect.left>=viewport.right||rect.bottom<=viewport.top||rect.top>=viewport.bottom)continue;const primary=paged?Math.max(rect.left,viewport.left):Math.max(rect.top,viewport.top),secondary=paged?Math.max(rect.top,viewport.top):Math.max(rect.left,viewport.left);if(!best||primary<best.primary||(primary===best.primary&&secondary<best.secondary))best={chapter,primary,secondary}}return best?best.chapter:null}
