  const chapter=speechChapterRoot(article,$('.reader'),startBlock,pageMode==='double');if(!chapter){notify('无法确定当前章节');return}stopSpeech();const blocks=[...chapter.querySelectorAll('[data-prose="true"]')];const queue=[];const segmenter=new Intl.Segmenter(undefined,{granularity:'sentence'});for(const block of blocks){const text=block.textContent;for(const part of segmenter.segment(text)){const leading=part.segment.length-part.segment.trimStart().length;const value=part.segment.trim();if(value)queue.push({block,start:part.index+leading,end:part.index+leading+value.length,text:value})}}
