  const synth=async item=>{const response=await fetch('/api/speech/synthesize',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text:item.text}),signal});if(!response.ok){const error=await response.json();throw Error(error.error||'未连接语音引擎，请前往 ⚙ 设置配置本地或云端 TTS 服务')}return response.blob()};
